// `.ivp` bundle: one file holding a project and its video.
//
//   "IVP1" | uint32 big-endian N | N bytes of project JSON (UTF-8) | video bytes
//
// Identical to what the Interactive Video mobile app exports and imports.

import { parseProject, stringifyProject, SdkError } from './schema.js';

const MAGIC = [0x49, 0x56, 0x50, 0x31]; // "IVP1"
const MAX_META_BYTES = 16 * 1024 * 1024;

const toBytes = (data) => (data instanceof Uint8Array ? data : new Uint8Array(data));

/**
 * Reads a bundle. `videoBytes` is a view into the input, not a copy.
 * @returns {{ project: object, videoBytes: Uint8Array }}
 */
export function readBundle(data) {
  const bytes = toBytes(data);
  if (bytes.length < 8 || MAGIC.some((b, i) => bytes[i] !== b)) {
    throw new SdkError('Not an Interactive Video bundle (.ivp)');
  }
  const metaLength = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength).getUint32(4);
  if (metaLength === 0 || metaLength > MAX_META_BYTES || 8 + metaLength > bytes.length) {
    throw new SdkError('The bundle is damaged or incomplete');
  }
  const json = new TextDecoder('utf-8', { fatal: true }).decode(bytes.subarray(8, 8 + metaLength));
  return {
    project: parseProject(json),
    videoBytes: bytes.subarray(8 + metaLength),
  };
}

/**
 * Builds a bundle from a normalised project and raw video bytes. The project's
 * `video` field is replaced by `videoName` (default "video.mp4").
 */
export function writeBundle(project, videoBytes, videoName = 'video.mp4') {
  const meta = new TextEncoder().encode(stringifyProject({ ...project, video: videoName }));
  const video = toBytes(videoBytes);
  const out = new Uint8Array(8 + meta.length + video.length);
  out.set(MAGIC, 0);
  new DataView(out.buffer).setUint32(4, meta.length);
  out.set(meta, 8);
  out.set(video, 8 + meta.length);
  return out;
}
