// Frame source for browsers: decodes a video off-screen and returns small
// grayscale frames for trackObject().
//
// The video must be same-origin or served with CORS headers
// (`Access-Control-Allow-Origin`), otherwise the browser blocks pixel reads.

import { SdkError } from './schema.js';

export class VideoFrameSource {
  /** @param {string} src video URL (http(s) or blob:) */
  constructor(src, { crossOrigin = 'anonymous', seekTimeoutMs = 8000 } = {}) {
    this.src = src;
    this.crossOrigin = crossOrigin;
    this.seekTimeoutMs = seekTimeoutMs;
    this.video = null;
    this.canvas = null;
    this.ctx = null;
  }

  async open() {
    if (this.video) return;
    const video = document.createElement('video');
    video.muted = true;
    video.preload = 'auto';
    video.playsInline = true;
    if (this.crossOrigin) video.crossOrigin = this.crossOrigin;
    video.src = this.src;
    await new Promise((resolve, reject) => {
      video.onloadeddata = resolve;
      video.onerror = () => reject(new SdkError('The video could not be loaded for tracking'));
    });
    this.video = video;
    this.canvas = document.createElement('canvas');
    this.ctx = this.canvas.getContext('2d', { willReadFrequently: true });
  }

  async getFrame(timeMs, width = 192) {
    await this.open();
    const { video, canvas, ctx } = this;
    const target = Math.min(Math.max(timeMs / 1000, 0), video.duration || 0);
    if (Math.abs(video.currentTime - target) > 0.0005) {
      await new Promise((resolve, reject) => {
        const timer = setTimeout(() => reject(new SdkError('Timed out seeking the video')), this.seekTimeoutMs);
        video.addEventListener('seeked', () => { clearTimeout(timer); resolve(); }, { once: true });
        video.currentTime = target;
      });
    }
    const height = Math.max(1, Math.round((video.videoHeight * width) / video.videoWidth));
    canvas.width = width;
    canvas.height = height;
    ctx.drawImage(video, 0, 0, width, height);
    let rgba;
    try {
      rgba = ctx.getImageData(0, 0, width, height).data;
    } catch {
      throw new SdkError('The browser blocked reading video pixels. Serve the video from the same origin or with CORS enabled.');
    }
    const data = new Uint8Array(width * height);
    for (let i = 0, p = 0; i < data.length; i++, p += 4) {
      data[i] = (rgba[p] * 299 + rgba[p + 1] * 587 + rgba[p + 2] * 114) / 1000;
    }
    return { width, height, data };
  }

  close() {
    if (this.video) {
      this.video.removeAttribute('src');
      this.video.load();
    }
    this.video = this.canvas = this.ctx = null;
  }
}
